                '<div class="time-row">' +
                    '<div class="form-group">' +
                        '<label>Start Time</label>' +
                        '<div class="time-inputs">' +
                            '<input type="time" id="startTime_' + index + '" class="time-input-native" value="' + pad2(schedule.startHour) + ':' + pad2(schedule.startMinute) + '">' +
                        '</div>' +
                    '</div>' +
                    '<div class="form-group">' +
                        '<label>End Time</label>' +
                        '<div class="time-inputs">' +
                            '<input type="time" id="endTime_' + index + '" class="time-input-native" value="' + pad2(schedule.endHour) + ':' + pad2(schedule.endMinute) + '">' +
                        '</div>' +
                    '</div>' +
                '</div>' +
                '<div class="validation-error" id="timeValidation_' + index + '"></div>' +

                '<div class="form-group">' +
                    '<label><input type="checkbox" id="cyclicCheck_' + index + '"' + (schedule.isCyclic ? ' checked' : '') + '> Is Cyclic</label>' +
                '</div>' +

                '<div class="form-group cyclic-fields" id="cyclicFieldsGroup_' + index + '"' + cyclicFieldsDisplay + '>' +
                    '<div class="time-row">' +
                        '<div class="form-group">' +
                            '<label>On Duration</label>' +
                            '<div class="time-inputs">' +
                                '<input type="number" id="onDurHrs_' + index + '" min="0" max="23" maxlength="2" inputmode="numeric" value="' + (schedule.onDurHrs || 0) + '" placeholder="HH">' +
                                '<span>:</span>' +
                                '<input type="number" id="onDurMins_' + index + '" min="0" max="59" maxlength="2" inputmode="numeric" value="' + pad2(schedule.onDurMins || 0) + '" placeholder="MM">' +
                            '</div>' +
                        '</div>' +
                        '<div class="form-group">' +
                            '<label>Off Duration</label>' +
                            '<div class="time-inputs">' +
                                '<input type="number" id="offDurHrs_' + index + '" min="0" max="23" maxlength="2" inputmode="numeric" value="' + (schedule.offDurHrs || 0) + '" placeholder="HH">' +
                                '<span>:</span>' +
                                '<input type="number" id="offDurMins_' + index + '" min="0" max="59" maxlength="2" inputmode="numeric" value="' + pad2(schedule.offDurMins || 0) + '" placeholder="MM">' +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                    '<div class="validation-error" id="cyclicValidation_' + index + '"></div>' +
                '</div>' +

                '<div class="validation-error" id="generalValidation_' + index + '"></div>' +
                '<div class="accordion-footer">' +
                    '<button type="button" class="btn-delete-accordion" data-index="' + index + '"><i class="fas fa-trash"></i> Delete</button>' +
                    '<div class="accordion-footer-right">' +
                        '<button type="button" class="btn-cancel-accordion" data-index="' + index + '">Cancel</button>' +
                        '<button type="button" class="btn-save-accordion" data-index="' + index + '">Save</button>' +
                    '</div>' +
                '</div>' +
            '</div>' +
        '</div>';

    var $accordion = $('<div class="schedule-accordion' + disabledClass + expandedClass + '" data-index="' + index + '">' + headerHtml + bodyHtml + '</div>');

    // Click header to toggle (but not on the enable switch)
    $accordion.find('.accordion-header').on('click', function(e) {
        if ($(e.target).closest('.schedule-enable-switch').length) return;
        toggleAccordion(index);
    });

    // Enable toggle (stop propagation to prevent accordion toggle)
    $accordion.find('.schedule-enable-checkbox').on('change', function(e) {
        e.stopPropagation();
        var enabled = $(this).prop('checked');
        self.ctx.scheduleData.schedule[index].enabled = enabled;
        // Don't auto-save a newly-created schedule that hasn't been saved yet;
        // its enabled state will be persisted when the schedule itself is saved.
        if (!self.ctx.scheduleData.schedule[index]._new) saveScheduleData();
        var schedItem = $(this).closest('.schedule-accordion');
        if (enabled) schedItem.removeClass('disabled'); else schedItem.addClass('disabled');
    });

    // Type select change
    $accordion.find('#typeSelect_' + index).on('change', function() {
        if ($(this).val() === 'weekly') $accordion.find('#daysGroup_' + index).show();
        else $accordion.find('#daysGroup_' + index).hide();
    });

    // Cyclic check toggle
    $accordion.find('#cyclicCheck_' + index).on('change', function() {
        if ($(this).prop('checked')) $accordion.find('#cyclicFieldsGroup_' + index).show();
        else $accordion.find('#cyclicFieldsGroup_' + index).hide();
    });

    // Pad on blur for time inputs
    $accordion.find('#onDurHrs_' + index + ', #offDurHrs_' + index).on('blur', function() { $(this).val(clampHour($(this).val())); });
    $accordion.find('#onDurMins_' + index + ', #offDurMins_' + index).on('blur', function() { var v = clampMinute($(this).val()); $(this).val(pad2(v)); });

    // Save button
    $accordion.find('.btn-save-accordion').on('click', function(e) {
        e.stopPropagation();
        saveAccordionSchedule(index, $accordion);
    });

    // Cancel button
    $accordion.find('.btn-cancel-accordion').on('click', function(e) {
        e.stopPropagation();
        // Discard a brand-new schedule that was never saved.
        if (self.ctx.scheduleData.schedule[index] && self.ctx.scheduleData.schedule[index]._new) {
            self.ctx.scheduleData.schedule.splice(index, 1);
        }
        self.ctx.expandedIndex = -1;
        renderScheduleList();
    });

    // Delete button
    $accordion.find('.btn-delete-accordion').on('click', function(e) {
        e.stopPropagation();
        deleteSchedule(index);
    });

    return $accordion;
}

function showValidationError($accordion, elementId, message) {
    var $el = $accordion.find('#' + elementId);
    $el.text(message).addClass('visible');
}

function clearValidationErrors($accordion, index) {
    $accordion.find('#timeValidation_' + index).text('').removeClass('visible');
    $accordion.find('#daysValidation_' + index).text('').removeClass('visible');
    $accordion.find('#cyclicValidation_' + index).text('').removeClass('visible');
    $accordion.find('#generalValidation_' + index).text('').removeClass('visible');
}

function saveAccordionSchedule(index, $accordion) {
    // Clear all previous validation errors
    clearValidationErrors($accordion, index);

    var type = $accordion.find('#typeSelect_' + index).val();
    var isCyclic = $accordion.find('#cyclicCheck_' + index).prop('checked');
    var startParts = ($accordion.find('#startTime_' + index).val() || '').split(':');
    var startHour = clampHour(startParts[0]);
    var startMinute = clampMinute(startParts[1]);
    var endParts = ($accordion.find('#endTime_' + index).val() || '').split(':');
    var endHour = clampHour(endParts[0]);
    var endMinute = clampMinute(endParts[1]);

    // Validate start time != end time
    if (startHour === endHour && startMinute === endMinute) {
        showValidationError($accordion, 'timeValidation_' + index, 'Start time and end time cannot be the same.');
        return;
    }

    var days = [];
    if (type === 'weekly') {
        $accordion.find('input[name="day_' + index + '"]:checked').each(function() { days.push($(this).val()); });
        if (days.length < 1) {
            showValidationError($accordion, 'daysValidation_' + index, 'Please select at least one day for weekly schedule.');
            return;
        }
    }

    var onDurHrs = clampHour($accordion.find('#onDurHrs_' + index).val());
    var onDurMins = clampMinute($accordion.find('#onDurMins_' + index).val());
    var offDurHrs = clampHour($accordion.find('#offDurHrs_' + index).val());
    var offDurMins = clampMinute($accordion.find('#offDurMins_' + index).val());

    // Cyclic validations
    if (isCyclic) {
        if (onDurHrs + onDurMins === 0 || offDurHrs + offDurMins === 0) {
            showValidationError($accordion, 'cyclicValidation_' + index, 'Please enter valid On and Off durations for cyclic schedule.');
            return;
        }
        var cyclicError = validateCyclicDuration(startHour, startMinute, endHour, endMinute, onDurHrs, onDurMins, offDurHrs, offDurMins);
        if (cyclicError) {
            showValidationError($accordion, 'cyclicValidation_' + index, cyclicError);
            return;
        }
    }

    var schedule = {
        isCyclic: isCyclic,
        enabled: self.ctx.scheduleData.schedule[index].enabled,
        type: type,
        days: days,
        startHour: pad2(startHour),
        startMinute: pad2(startMinute),
        endHour: pad2(endHour),
        endMinute: pad2(endMinute),
        onDurHrs: onDurHrs,
        onDurMins: onDurMins,
        offDurHrs: offDurHrs,
        offDurMins: offDurMins
    };

    var tempSchedules = self.ctx.scheduleData.schedule.slice(0);
    tempSchedules[index] = schedule;
    if (!validateSchedulesForClash(tempSchedules)) {
        showValidationError($accordion, 'generalValidation_' + index, 'There is an overlap in the schedules. Please correct the timing.');
        return;
    }

    self.ctx.scheduleData.schedule[index] = schedule;
    self.ctx.expandedIndex = -1;
    saveScheduleData();
    renderScheduleList();
}

function deleteSchedule(index) {
    if (confirm('Are you sure you want to delete this schedule?')) {
        self.ctx.scheduleData.schedule.splice(index, 1);
        self.ctx.expandedIndex = -1;
        saveScheduleData();
        renderScheduleList();
    }
}

function loadScheduleData() {
    console.log('=== LOADING SCHEDULE DATA ===');
    getTargetEntityId(function(targetEntityId) {
        if (!targetEntityId) {
            if (loadRetryCount < maxRetries) {
                loadRetryCount++;
                console.log('Retrying in 500ms... (' + loadRetryCount + '/' + maxRetries + ')');
                setTimeout(function() { loadScheduleData(); }, 500);
            } else {
                console.error('Max retries reached. Entity not found.');
                renderScheduleList();
            }
            return;
        }

        console.log('Target Entity:', targetEntityId);

        self.ctx.attributeService.getEntityAttributes(
            targetEntityId,
            'CLIENT_SCOPE',
            ['schedule', 'firmwareMajor', 'firmwareMinor', 'firmwarePatch', 'firmwareVersion']
        ).subscribe(
            function(attributes) {
                console.log('Loaded attributes:', attributes);
                var attrMap = {};
                if (attributes && attributes.length > 0) {
                    for (var i = 0; i < attributes.length; i++) {
                        var a = attributes[i];
                        var k = a.key !== undefined ? a.key : (a.attributeKey !== undefined ? a.attributeKey : null);
                        if (k) attrMap[k] = a.value;
                    }
                }
                updateFirmwareBanner(attrMap);
                lastSuccessfulLoad = Date.now();
                var scheduleVal = attrMap.schedule;
                if (scheduleVal !== undefined && scheduleVal !== null) {
                    try {
                        var raw = typeof scheduleVal === 'string' ? JSON.parse(scheduleVal) : scheduleVal;
                        var arr = raw.s != null ? raw.s : (raw.schedule || []);
                        self.ctx.scheduleData.schedule = arr.map(function(item) {
                            if (item.t != null || item['1'] != null) return fromCompactItem(item);
                            return item;
                        });
                        console.log('Loaded existing schedule data:', self.ctx.scheduleData);
                    } catch (e) {
                        console.error('Error parsing schedule data:', e);
                        self.ctx.scheduleData.schedule = [];
                    }
                } else {
                    self.ctx.scheduleData.schedule = [];
                }
                renderScheduleList();
            },
            function(error) {
                console.log('Error loading attributes:', error);
                self.ctx.scheduleData.schedule = [];
                renderScheduleList();
            }
        );
    });
}

function getTargetEntityId(callback) {
    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.datasources) {
        var datasources = self.ctx.defaultSubscription.datasources;
        if (datasources && datasources.length > 0) {
            var ds = datasources[0];
            if (ds.entity && ds.entity.id) { callback(ds.entity); return; }
            if (ds.entityAliasId && self.ctx.aliasController) {
                var aliasInfo = self.ctx.aliasController.getInstantAliasInfo(ds.entityAliasId);
                if (aliasInfo) {
                    if (aliasInfo.currentEntity) { callback(aliasInfo.currentEntity); return; }
                    if (aliasInfo.resolvedEntities && aliasInfo.resolvedEntities.length > 0) { callback(aliasInfo.resolvedEntities[0]); return; }
                    if (aliasInfo.stateEntity === true) {
                        var stateEntity = getEntityFromState();
                        if (stateEntity) { callback(stateEntity); return; }
                    }
                }
                try {
                    var aliasInfoObs = self.ctx.aliasController.getAliasInfo(ds.entityAliasId);
                    if (aliasInfoObs && aliasInfoObs.subscribe) {
                        aliasInfoObs.subscribe(
                            function(info) {
                                if (info && info.currentEntity) { callback(info.currentEntity); return; }
                                if (info && info.resolvedEntities && info.resolvedEntities.length > 0) { callback(info.resolvedEntities[0]); return; }
                                fallbackGetEntity(callback);
                            },
                            function(error) { fallbackGetEntity(callback); }
                        );
                        return;
                    }
                } catch (e) {}
            }
        }
    }
    fallbackGetEntity(callback);
}

function getEntityFromState() {
    if (self.ctx.dashboardCtx && self.ctx.dashboardCtx.stateController) {
        var state = self.ctx.dashboardCtx.stateController.getStateParams();
        if (state) {
            if (state.targetEntityId && state.targetEntityId.id) return state.targetEntityId;
            if (state.entityId) {
                if (state.entityId.id && state.entityId.entityType) return state.entityId;
                else if (typeof state.entityId === 'string') return {id: state.entityId, entityType: 'DEVICE'};
            }
        }
    }
    return null;
}

function fallbackGetEntity(callback) {
    var stateEntity = getEntityFromState();
    if (stateEntity) { callback(stateEntity); return; }
    if (self.ctx.datasources && self.ctx.datasources.length > 0) {
        var ds = self.ctx.datasources[0];
        if (ds.entity && ds.entity.id) { callback(ds.entity.id); return; }
    }
    if (self.ctx.aliasController && self.ctx.aliasController.resolvedAliases) {
        var resolved = self.ctx.aliasController.resolvedAliases;
        if (resolved && Object.keys(resolved).length > 0) {
            for (var key in resolved) {
                var alias = resolved[key];
                if (alias.currentEntity) { callback(alias.currentEntity); return; }
                if (alias.stateEntity) { callback(alias.stateEntity); return; }
                if (alias.entity) { callback(alias.entity); return; }
                if (alias.resolvedEntities && alias.resolvedEntities.length > 0) { callback(alias.resolvedEntities[0]); return; }
            }
        }
    }
    callback(null);
}

function saveScheduleData() {
    console.log('=== SAVING SCHEDULE DATA ===');
    getTargetEntityId(function(targetEntityId) {
        if (!targetEntityId) {
            console.error('No target entity found');
            alert('Cannot auto-save: No target device found.');
            showJsonForManualSave();
            return;
        }
        if (!targetEntityId.id || !targetEntityId.entityType) {
            console.error('Invalid entity structure');
            alert('Error: Invalid entity structure');
            showJsonForManualSave();
            return;
        }

        var compactPayload = { s: self.ctx.scheduleData.schedule.map(toCompactItem) };
        var jsonValue = JSON.stringify(compactPayload);
        var attributes = [{ key: 'schedule', value: jsonValue }];

        self.ctx.attributeService.saveEntityAttributes(
            targetEntityId,
            'SHARED_SCOPE',
            attributes
        ).subscribe(
            function(response) {
                console.log('Save request accepted, waiting for device to update...');
                var statusEl = self.ctx.$container.find('#scheduleSaveStatus');
                statusEl.removeClass('pending success failed').addClass('pending');
                statusEl.html('<i class="fas fa-spinner fa-spin"></i> Schedule is being updated to device...');
                statusEl.css('display', 'flex');
                self.ctx._saveExpectedJson = jsonValue;
                self.ctx._saveTargetEntityId = targetEntityId;
                self.ctx._savePollStart = Date.now();
                self.ctx._savePollTimer = setTimeout(function doPoll() {
                    var elapsed = Date.now() - self.ctx._savePollStart;
                    if (elapsed >= 30000) {
                        self.ctx._savePollTimer = null;
                        statusEl.removeClass('pending success').addClass('failed');
                        statusEl.html('<i class="fas fa-exclamation-circle"></i> Device update failed. The device may be offline. Please try again.');
                        return;
                    }
                    self.ctx.attributeService.getEntityAttributes(self.ctx._saveTargetEntityId, 'CLIENT_SCOPE', ['schedule']).subscribe(
                        function(attrs) {
                            var elapsed2 = Date.now() - self.ctx._savePollStart;
                            if (elapsed2 >= 30000) {
                                self.ctx._savePollTimer = null;
                                statusEl.removeClass('pending success').addClass('failed');
                                statusEl.html('<i class="fas fa-exclamation-circle"></i> Device update failed. The device may be offline. Please try again.');
                                return;
                            }
                            var received = null;
                            if (attrs && attrs.length > 0) {
                                for (var i = 0; i < attrs.length; i++) {
                                    var a = attrs[i];
                                    var k = a.key !== undefined ? a.key : (a.attributeKey !== undefined ? a.attributeKey : null);
                                    if (k === 'schedule') { received = a.value; break; }
                                }
                            }
                            try {
                                var expObj = JSON.parse(self.ctx._saveExpectedJson);
                                var recvStr = typeof received === 'string' ? received : (received != null ? JSON.stringify(received) : '');
                                var recvObj = recvStr ? JSON.parse(recvStr) : null;
                                if (recvObj && deepEqual(expObj, recvObj)) {
                                    self.ctx._savePollTimer = null;
                                    statusEl.removeClass('pending failed').addClass('success');
                                    statusEl.html('<i class="fas fa-check-circle"></i> Schedule saved successfully!');
                                    if (self.ctx.detectChanges) self.ctx.detectChanges();
                                    setTimeout(function() { statusEl.css('display', 'none'); }, 4000);
                                    return;
                                }
                            } catch (e) {}
                            self.ctx._savePollTimer = setTimeout(doPoll, 3000);
                        },
                        function(err) {
                            var elapsed2 = Date.now() - self.ctx._savePollStart;
                            if (elapsed2 >= 30000) {
                                self.ctx._savePollTimer = null;
                                statusEl.removeClass('pending success').addClass('failed');
                                statusEl.html('<i class="fas fa-exclamation-circle"></i> Device update failed. Please try again.');
                            } else {
                                self.ctx._savePollTimer = setTimeout(doPoll, 3000);
                            }
                        }
                    );
                }, 4000);
            },
            function(error) {
                self.ctx.$container.find('#scheduleSaveStatus').css('display', 'none');
                if (self.ctx._savePollTimer) { clearTimeout(self.ctx._savePollTimer); self.ctx._savePollTimer = null; }
                console.error('SAVE FAILED:', error);
                var errorMsg = 'Failed to save schedule.\n\n';
                if (error.status === 403) errorMsg += 'Permission denied.';
                else if (error.status === 404) errorMsg += 'Device not found.';
                else if (error.message) errorMsg += 'Error: ' + error.message;
                else errorMsg += 'Error: ' + (error.statusText || 'Unknown error');
                alert(errorMsg);
                showJsonForManualSave();
            }
        );
    });
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (a == null || b == null) return false;
  if (typeof a !== 'object' || typeof b !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (var i = 0; i < a.length; i++) { if (!deepEqual(a[i], b[i])) return false; }
    return true;
  }
  var aKeys = Object.keys(a);
  var bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  for (var i = 0; i < aKeys.length; i++) {
    var k = aKeys[i];
    if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
    if (!deepEqual(a[k], b[k])) return false;
  }
  return true;
}

