}

// === Session Keep-Alive & Recovery ===
function startSessionKeepAlive() {
    // 1. visibilitychange — reload data when page/webview becomes visible again
    visibilityHandler = function() {
        if (!document.hidden) {
            console.log('[Schedule] Page became visible, checking session health...');
            var timeSinceLastLoad = Date.now() - lastSuccessfulLoad;
            if (timeSinceLastLoad > SESSION_STALE_THRESHOLD) {
                console.log('[Schedule] Session likely stale (last load ' + Math.round(timeSinceLastLoad/1000) + 's ago), reloading data...');
                loadRetryCount = 0;
                loadScheduleData();
            }
        }
    };
    document.addEventListener('visibilitychange', visibilityHandler);

    // 2. Periodic health check — lightweight attribute read every 60s
    sessionHealthTimer = setInterval(function() {
        if (document.hidden) return; // Don't check when page is hidden
        var timeSinceLastLoad = Date.now() - lastSuccessfulLoad;
        if (timeSinceLastLoad > SESSION_STALE_THRESHOLD) {
            console.log('[Schedule] Periodic health check: session may be stale, reloading...');
            loadRetryCount = 0;
            loadScheduleData();
        } else {
            // Lightweight ping — just read one attribute to keep the WS subscription alive
            getTargetEntityId(function(entity) {
                if (!entity) return;
                self.ctx.attributeService.getEntityAttributes(entity, 'CLIENT_SCOPE', ['schedule']).subscribe(
                    function() { /* success — session is alive */ },
                    function(err) {
                        console.warn('[Schedule] Health check failed, session may be lost:', err);
                        // Force a full reload after a short delay
                        setTimeout(function() {
                            loadRetryCount = 0;
                            loadScheduleData();
                        }, 1000);
                    }
                );
            });
        }
    }, SESSION_HEALTH_INTERVAL);

    // 3. pageshow event — catches back/forward cache restores (bfcache)
    window.addEventListener('pageshow', function(e) {
        if (e.persisted) {
            console.log('[Schedule] Page restored from bfcache, reloading data...');
            loadRetryCount = 0;
            loadScheduleData();
        }
    });

    // 4. online event — network came back
    window.addEventListener('online', function() {
        console.log('[Schedule] Network came back online, reloading data...');
        setTimeout(function() {
            loadRetryCount = 0;
            loadScheduleData();
        }, 2000); // Wait a moment for WS to reconnect
    });

    console.log('[Schedule] Session keep-alive started');
}

function stopSessionKeepAlive() {
    if (sessionHealthTimer) { clearInterval(sessionHealthTimer); sessionHealthTimer = null; }
    if (visibilityHandler) { document.removeEventListener('visibilitychange', visibilityHandler); visibilityHandler = null; }
}

self.onDataUpdated = function() {
    console.log('Widget data updated - reloading schedules');
    loadScheduleData();
}

self.onDestroy = function() {
    stopSessionKeepAlive();
    if (self.ctx._savePollTimer) {
        clearTimeout(self.ctx._savePollTimer);
        self.ctx._savePollTimer = null;
    }
    console.log('Widget destroyed');
}
